import React, { useEffect, useState } from 'react';
import AuthPage from './components/Authpage/Authpage';
import { auth } from './firebaseConfig';
import { onAuthStateChanged, signOut } from 'firebase/auth';

function App() {
  const [user, setUser] = useState(null); // Estado para guardar la información del usuario logeado

  useEffect(() => {
    // Suscribe un observador al estado de autenticación de Firebase
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser); // Actualiza el estado con el usuario actual
      console.log("Estado de autenticación cambiado:", currentUser);
    });

    // Devuelve una función de limpieza para desuscribirse cuando el componente se desmonte
    return () => unsubscribe();
  }, []); // El array vacío asegura que se ejecute solo una vez al montar

  const handleLogout = async () => {
    try {
      await signOut(auth);
      console.log("Sesión cerrada exitosamente.");
    } catch (error) {
      console.error("Error al cerrar sesión:", error.message);
    }
  };

  return (
    <div className="App">
      {user ? (
        // Si hay un usuario logeado, muestra un mensaje de bienvenida y el botón de logout
        <div style={{ textAlign: 'center', marginTop: '50px' }}>
          <h2>¡Bienvenido, {user.email || user.displayName || 'Invitado'}!</h2>
          <p>UID: {user.uid}</p>
          <button onClick={handleLogout} style={{ padding: '10px 20px', fontSize: '16px', cursor: 'pointer' }}>
            Cerrar Sesión
          </button>
        </div>
      ) : (
        <AuthPage />
      )}
    </div>
  );
}

export default App;
